use crate::store_db::StoreDb;
use crate::{Complexity, Experiment};
pub struct SqliteTemporal { db: StoreDb, path: std::path::PathBuf, rev:i64, writes:u64 }
static SEQ:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);
impl Default for SqliteTemporal { fn default()->Self { let id=SEQ.fetch_add(1,std::sync::atomic::Ordering::Relaxed);let path=std::env::temp_dir().join(format!("labkit_temporal_{}_{}.db",std::process::id(),id));let _=std::fs::remove_file(&path);let db=StoreDb::file(&path);db.exec("CREATE TABLE fact(key INTEGER NOT NULL, tt_from INTEGER NOT NULL, tt_to INTEGER, weight INTEGER NOT NULL, PRIMARY KEY(key,tt_from)) WITHOUT ROWID; CREATE INDEX ix_live ON fact(key) WHERE tt_to IS NULL; CREATE TEMP TABLE d(key INTEGER PRIMARY KEY,dw INTEGER)");Self{db,path,rev:0,writes:0} } }
impl Drop for SqliteTemporal { fn drop(&mut self){let _=std::fs::remove_file(&self.path);let _=std::fs::remove_file(format!("{}-wal",self.path.display()));let _=std::fs::remove_file(format!("{}-shm",self.path.display()));} }
impl SqliteTemporal { fn commit(&mut self,d:&[(i64,i64)]) {if d.is_empty(){return}self.rev+=1;let values=d.iter().map(|(k,w)|format!("({k},{w})")).collect::<Vec<_>>().join(",");self.db.exec(format!("DELETE FROM d; INSERT INTO d(key,dw) VALUES {values} ON CONFLICT(key) DO UPDATE SET dw=dw+excluded.dw; INSERT INTO fact(key,tt_from,tt_to,weight) SELECT d.key,{r},NULL,0 FROM d LEFT JOIN fact f ON f.key=d.key AND f.tt_to IS NULL WHERE f.key IS NULL AND d.dw>0; UPDATE fact SET weight=weight+(SELECT dw FROM d WHERE d.key=fact.key) WHERE tt_to IS NULL AND key IN (SELECT key FROM d); UPDATE fact SET tt_to={r} WHERE tt_to IS NULL AND weight<=0 AND key IN (SELECT key FROM d)",r=self.rev));self.writes+=5;} fn keys(&self)->Vec<i64>{self.db.rows("SELECT key FROM fact WHERE tt_to IS NULL").into_iter().map(|r|r.try_get_by_index(0).unwrap()).collect()} }
impl Experiment for SqliteTemporal {fn name(&self)->&'static str{"sqlite-temporal"}fn complexity(&self)->Complexity{Complexity{time:"O(Δ·log n)",space:"O(working set) RSS"}}fn rationale(&self)->&'static str{"file-backed bitemporal fact table"}fn reset(&mut self){*self=Self::default()}fn setup(&mut self,b:usize){self.commit(&(0..b as i64).map(|k|(k,1)).collect::<Vec<_>>())}fn tick(&mut self,a:&[i64],r:&[i64]){let mut d=a.iter().map(|k|(*k,1)).collect::<Vec<_>>();d.extend(r.iter().map(|k|(*k,-1)));self.commit(&d)}fn digest(&self)->i64{self.keys().into_iter().fold(0,|a,k|a^crate::mix(k))}fn live(&self)->u64{self.keys().len() as u64}fn total_rows(&self)->u64{self.db.rows("SELECT key FROM fact").len() as u64}fn writes(&self)->u64{self.writes}fn plan_snapshot(&self)->Option<String>{Some("    index-driven temporal update\n".into())}}
